// Performance Helpers
public class ExtensionPerformanceTracker : IDisposable
{
    private readonly Stopwatch _stopwatch;
    private readonly ILogger _logger;
    private readonly string _extensionId;

    public ExtensionPerformanceTracker(ILogger logger, string extensionId)
    {
        _logger = logger;
        _extensionId = extensionId;
        _stopwatch = Stopwatch.StartNew();
    }

    public void Dispose()
    {
        _stopwatch.Stop();
        _logger.LogInformation(
            "Extension {ExtensionId} execution time: {Duration}ms",
            _extensionId,
            _stopwatch.ElapsedMilliseconds);
    }
}
