// Test Base Class
public abstract class ExtensionTestBase<TExtension> : IDisposable
    where TExtension : IExtension
{
    protected ServiceProvider ServiceProvider { get; private set; }
    protected Mock<IConfiguration> MockConfiguration { get; private set; }
    protected Mock<ILogger<TExtension>> MockLogger { get; private set; }

    protected ExtensionTestBase()
    {
        var services = new ServiceCollection();

        MockConfiguration = new Mock<IConfiguration>();
        MockLogger = new Mock<ILogger<TExtension>>();

        services.AddSingleton(MockConfiguration.Object);
        services.AddSingleton(MockLogger.Object);

        ConfigureServices(services);

        ServiceProvider = services.BuildServiceProvider();
    }

    protected abstract void ConfigureServices(IServiceCollection services);

    public void Dispose()
    {
        ServiceProvider?.Dispose();
    }
}
