```csharp
// File: ExtensionConfigurationExtensions.cs
namespace Gainwell.Extensions.SDK.Helpers
{
    public static class ExtensionConfigurationExtensions
    {
        /// <summary>
        /// Gets extension-specific configuration section.
        /// </summary>
        public static IConfigurationSection GetExtensionSection(
            this IConfiguration config,
            string extensionId)
        {
            return config.GetSection($"Extensions:{extensionId}");
        }

        /// <summary>
        /// Gets strongly-typed extension settings.
        /// </summary>
        public static T GetExtensionSettings<T>(
            this IConfiguration config,
            string extensionId)
            where T : new()
        {
            var section = config.GetExtensionSection(extensionId);
            var settings = new T();
            section.Bind(settings);
            return settings;
        }

        /// <summary>
        /// Validates required settings are present.
        /// </summary>
        public static void ValidateExtensionSettings(
            this IConfiguration config,
            string extensionId,
            params string[] requiredKeys)
        {
            var section = config.GetExtensionSection(extensionId);
            var missing = requiredKeys
                .Where(key => section[key] == null)
                .ToList();

            if (missing.Any())
            {
                throw new InvalidOperationException(
                    $"Extension {extensionId} missing required settings: " +
                    string.Join(", ", missing));
            }
        }
    }
}
```

