// File: Program.cs in Gainwell.Extensions.CLI
using System.CommandLine;
using System.CommandLine.Invocation;

namespace Gainwell.Extensions.CLI
{
    class Program
    {
        static async Task<int> Main(string[] args)
        {
            var rootCommand = new RootCommand("Gainwell Extensions CLI");

            // New command
            var newCommand = new Command("new", "Create new extension project")
            {
                new Option<string>("--name", "Project name") { IsRequired = true },
                new Option<string>("--state", () => "StateA", "State identifier"),
                new Option<string>("--type", () => "Validation", "Extension type"),
                new Option<string>("--output", () => ".", "Output directory")
            };
            newCommand.Handler = CommandHandler.Create<NewOptions>(HandleNew);
            rootCommand.AddCommand(newCommand);

            // Validate command
            var validateCommand = new Command("validate", "Validate extension project")
            {
                new Option<string>("--project", "Project file path") { IsRequired = true }
            };
            validateCommand.Handler = CommandHandler.Create<ValidateOptions>(HandleValidate);
            rootCommand.AddCommand(validateCommand);

            // Pack command
            var packCommand = new Command("pack", "Package extension for deployment")
            {
                new Option<string>("--project", "Project file path") { IsRequired = true },
                new Option<string>("--output", () => "./dist", "Output directory")
            };
            packCommand.Handler = CommandHandler.Create<PackOptions>(HandlePack);
            rootCommand.AddCommand(packCommand);

            return await rootCommand.InvokeAsync(args);
        }

        static Task<int> HandleNew(NewOptions options)
        {
            Console.WriteLine($"Creating extension project: {options.Name}");
            Console.WriteLine($"  State: {options.State}");
            Console.WriteLine($"  Type: {options.Type}");
            Console.WriteLine($"  Output: {options.Output}");

            // Execute: dotnet new gainwell-{type}-ext --name {name} --state {state}
            var templateName = $"gainwell-{options.Type.ToLower()}-ext";
            var process = Process.Start("dotnet",
                $"new {templateName} --name {options.Name} --state {options.State} --output {options.Output}");
            process.WaitForExit();

            return Task.FromResult(process.ExitCode);
        }
    }
}
```

