### Step 2: Implement validation logic

Open `ClaimsValidationExtension.cs` and implement `ValidateAsync`:

```csharp
public override async Task<ValidationResult> ValidateAsync(
    ClaimValidationContext context,
    CancellationToken cancellationToken)
{
    var claim = context.Claim;

    // Validate claim has required fields
    if (string.IsNullOrEmpty(claim.MemberId))
    {
        return Failure("Member ID is required");
    }

    if (claim.ServiceDate > DateTime.Today)
    {
        return Failure("Service date cannot be in the future");
    }

    // Validate state-specific rules
    if (claim.State == "StateA" && claim.Amount > 10000)
    {
        Logger.LogWarning(
            "High-value claim requires manual review: {ClaimId}",
            claim.ClaimId);
    }

    return Success();
}
