using Gainwell.ExtensionSDK;
using Gainwell.ExtensionSDK.Claims;

[Extension("florida-claims-ext", "1.2.0")]
[Description("Florida-specific claims processing customizations")]
[Author("Florida Medicaid Team")]
[SupportedProduct("ClaimsProcessing", "5.0+")]
public class FloridaClaimsExtension : ClaimExtensionBase
{
    public override void ConfigureServices(IExtensionServiceCollection services)
    {
        // Register Florida-specific services
        services.AddScoped<IClaimValidator, FloridaClaimValidator>();
        services.AddScoped<IClaimPricer, FloridaFeeSchedulePricer>();

        // Register configuration
        services.Configure<FloridaClaimOptions>(Configuration.GetSection("Florida"));
    }

    public override async Task<ClaimProcessingResult> ProcessClaimAsync(
        ClaimContext context,
        CancellationToken cancellationToken)
    {
        var validator = context.GetService<IClaimValidator>();
        var pricer = context.GetService<IClaimPricer>();

        // Florida-specific validation
        var validationResult = await validator.ValidateAsync(
            context.Claim, cancellationToken);

        if (!validationResult.IsValid)
        {
            return ClaimProcessingResult.Denied(validationResult.Errors);
        }

        // Apply Florida fee schedule
        var pricedClaim = await pricer.PriceClaimAsync(
            context.Claim, cancellationToken);

        return ClaimProcessingResult.Approved(pricedClaim);
    }
}
```

